-- SnapSTL shared order records (Supabase / Postgres). Generated by `uv run snapstl-db schema`;
-- paste into Supabase → SQL Editor → Run. Safe to run again. SnapSTL creates the same by itself
-- the first time it connects (Settings → Shared order records).
CREATE SCHEMA IF NOT EXISTS snapstl;
CREATE TABLE IF NOT EXISTS snapstl.order_records (
    order_id        text PRIMARY KEY,
    clubbed_id      text,
    order_date      text,
    sku             text,
    quantity        integer,
    customer_name   text,
    phone           text,
    address         text,
    raw_name        text,
    raw_color       text,
    special_request text,
    name            text,
    color           text,
    source_status   text,
    status_at       text,
    state           text NOT NULL CHECK (state IN ('in_batch', 'bundled', 'printed', 'released')),
    state_at        double precision NOT NULL,
    batch_uid       text,
    batch_label     text,
    computer_id     text,
    computer_name   text,
    bundled_at      double precision,
    printed_at      double precision,
    created_at      timestamptz NOT NULL DEFAULT now(),
    updated_at      timestamptz NOT NULL DEFAULT clock_timestamp(),
    updated_by      text
);
CREATE INDEX IF NOT EXISTS order_records_updated ON snapstl.order_records (updated_at);
CREATE TABLE IF NOT EXISTS snapstl.batch_records (
    uid           text PRIMARY KEY,
    computer_id   text,
    computer_name text,
    local_id      integer,
    label         text,
    status        text,
    created_at    double precision,
    finished_at   double precision,
    order_ids     text,
    orders        integer,
    plates        integer,
    folder        text,
    updated_at    timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE TABLE IF NOT EXISTS snapstl.meta (key text PRIMARY KEY, value text);
-- A new id every time the records are created (again, after Clear / Reset with "also clear Supabase"):
-- each computer notices it changed and makes itself match the empty records (sync._follow_reset).
INSERT INTO snapstl.meta(key, value) VALUES ('instance', gen_random_uuid()::text) ON CONFLICT (key) DO NOTHING;
CREATE OR REPLACE FUNCTION snapstl.refuse_delete() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'SnapSTL records are never deleted (% on %.%)', TG_OP, TG_TABLE_SCHEMA, TG_TABLE_NAME;
END $$;
CREATE OR REPLACE TRIGGER order_records_no_delete BEFORE DELETE ON snapstl.order_records
    FOR EACH ROW EXECUTE FUNCTION snapstl.refuse_delete();
CREATE OR REPLACE TRIGGER order_records_no_truncate BEFORE TRUNCATE ON snapstl.order_records
    FOR EACH STATEMENT EXECUTE FUNCTION snapstl.refuse_delete();
CREATE OR REPLACE TRIGGER batch_records_no_delete BEFORE DELETE ON snapstl.batch_records
    FOR EACH ROW EXECUTE FUNCTION snapstl.refuse_delete();
CREATE OR REPLACE TRIGGER batch_records_no_truncate BEFORE TRUNCATE ON snapstl.batch_records
    FOR EACH STATEMENT EXECUTE FUNCTION snapstl.refuse_delete();
-- Only SnapSTL (the database owner, through the connection string) reads or writes these tables.
-- Row level security with no policies refuses everyone else, and Supabase's API roles get no access
-- even if the schema is ever exposed in the Data API settings. The owner bypasses RLS.
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['order_records', 'batch_records', 'meta'] LOOP
    IF NOT (SELECT relrowsecurity FROM pg_class WHERE oid = format('snapstl.%I', t)::regclass) THEN
      EXECUTE format('ALTER TABLE snapstl.%I ENABLE ROW LEVEL SECURITY', t);
    END IF;
  END LOOP;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon')
     AND EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN
    REVOKE ALL ON SCHEMA snapstl FROM anon, authenticated;
    REVOKE ALL ON ALL TABLES IN SCHEMA snapstl FROM anon, authenticated;
  END IF;
END $$;
INSERT INTO snapstl.meta(key, value) VALUES ('schema_version', '1')
    ON CONFLICT (key) DO NOTHING;
